const items = $input.all();
const list = items.map(i => i.json).filter(j => j.id);
console.log('Total jobs with id:', list.length);

// Broader, single-word keywords so "AI Engineer", "automation specialist", etc. all match
const keywords = ['automation', 'n8n', 'workflow', 'ai', 'low-code', 'no-code', 'zapier', 'rpa', 'integration'];

const matched = list.filter(job => {
  const haystack = `${job.position || ''} ${job.description || ''} ${(job.tags || []).join(' ')}`.toLowerCase();
  return keywords.some(k => haystack.includes(k));
});
console.log('Matched by keyword:', matched.length);

// Widen the recency window to 14 days so it's not filtering everything out
const fourteenDaysAgo = Date.now() - 14 * 24 * 60 * 60 * 1000;
const recent = matched.filter(job => {
  const posted = new Date(job.date).getTime();
  return isNaN(posted) ? true : posted >= fourteenDaysAgo;
});
console.log('Recent + matched:', recent.length);

return recent.map(job => ({
  json: {
    id: job.id,
    position: job.position,
    company: job.company,
    url: job.url || job.apply_url,
    description: job.description,
    tags: job.tags,
    date: job.date
  }
}));

const job = $json;
const resumeText = $('Extract Resume Text').item.json.text;

const systemPrompt = `You are an expert technical recruiter. Compare the candidate's resume against the job description and return ONLY valid JSON with this exact shape: {"matchScore": number (0-10), "matchedSkills": string[], "gaps": string[], "reasoning": string}. No text outside the JSON object.`;

const userPrompt = `JOB TITLE: ${job.position}
COMPANY: ${job.company}
JOB DESCRIPTION:
${job.description}

CANDIDATE RESUME:
${resumeText}

Score the match 0-10 and return the JSON described in the system prompt.`;

return [{
  json: {
    ...job,
    openAiPayload: {
      model: 'gpt-4o-mini',
      temperature: 0.2,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ]
    }
  }
}];

const raw = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '{}';
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { matchScore: 0, matchedSkills: [], gaps: [], reasoning: 'Could not parse AI response: ' + raw };
}

const job = $('Filter & Normalize Jobs').item.json;

return [{
  json: {
    ...job,
    matchScore: parsed.matchScore,
    matchedSkills: parsed.matchedSkills,
    gaps: parsed.gaps,
    reasoning: parsed.reasoning
  }
}];

const job = $json;
const resumeText = $('Extract Resume Text').item.json.text;

const systemPrompt = `You are an expert resume writer. Rewrite the candidate's resume tailored to the specific job below - emphasize relevant skills and achievements, stay truthful (never invent experience), and keep a similar overall length/format to the original. Also write a concise 3-paragraph cover letter for this role. Return ONLY valid JSON: {"tailoredResume": string, "coverLetter": string}.`;

const userPrompt = `JOB TITLE: ${job.position}
COMPANY: ${job.company}
JOB DESCRIPTION:
${job.description}

MATCH NOTES: matched skills: ${(job.matchedSkills || []).join(', ')}; gaps: ${(job.gaps || []).join(', ')}

ORIGINAL RESUME:
${resumeText}`;

return [{
  json: {
    ...job,
    openAiPayload: {
      model: 'gpt-4o-mini',
      temperature: 0.4,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ]
    }
  }
}];

const raw = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '{}';
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { tailoredResume: raw, coverLetter: '' };
}

const job = $('Parse Match Score').item.json;
const safeCompany = (job.company || 'company').toString().replace(/[^a-z0-9]+/gi, '_');
const safePosition = (job.position || 'role').toString().replace(/[^a-z0-9]+/gi, '_');

return [{
  json: {
    ...job,
    tailoredResume: parsed.tailoredResume,
    coverLetter: parsed.coverLetter,
    fileName: `Resume_${safeCompany}_${safePosition}.txt`
  }
}];

